import {dataStatus,series as defaultCatalog} from './data.js';
import {heading,panel,table,button,chart,escapeHtml as esc} from './ui.js';
import {stitchDeskContracts} from './stitch-desk-contracts.js';
import {deskSeries,deskValue,last,finite,exactChange,clampedMonthDate,fxScenario,distribution,specialistDeskChartCatalog} from './specialist-desks.js';
const missing='Unavailable';
const numeric=(v,p=2,s='')=>finite(v)?v.toLocaleString('en-US',{minimumFractionDigits:p,maximumFractionDigits:p})+s:missing;
const money=v=>finite(v)?`${v<0?'−':''}$${Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}B`:missing;
const note=t=>`<p class="panel-note">${esc(t)}</p>`;
const status=t=>`<span class="specialist-status">${esc(t)}</span>`;
function kpis(ctx,items){return `<section class="specialist-kpis specialist-kpis-${items.length}" aria-label="${esc(ctx.contract.title)} headline readings">${items.map(item=>{const s=item.id?ctx.get(item.id):null,r=last(s),value=Object.hasOwn(item,'value')?item.value:deskValue(s,r);return `<article class="specialist-kpi metric"${item.id?` data-specialist-input="${esc(item.id)}"`:''}><div class="specialist-kpi-label">${esc(item.label??s?.name??item.id)}</div><strong class="specialist-kpi-value">${esc(value??missing)}</strong><span class="specialist-kpi-detail">${esc(item.detail??(s?.observationType==='model-estimate'?'Staff model estimate':s?.observationType==='calculated'?'Calculated from official inputs':'Official source observation'))}</span><small>${esc(item.basis??`${r?.date??'Reference date unavailable'}${s?.unit?' · '+s.unit:''}`)}</small></article>`;}).join('')}</section>`;}
function pillars(items){return `<section class="specialist-pillars" aria-label="Analytical framework">${items.map(([title,text,value])=>`<article><span class="eyebrow">Research framework</span><h2>${esc(title)}</h2>${value?`<strong>${esc(value)}</strong>`:''}<p>${esc(text)}</p></article>`).join('')}</section>`;}
const grid=(left,right,ratio='21')=>`<div class="specialist-grid specialist-grid-${ratio}">${left}${right}</div>`;
function unavailableChart(title,text){return `<div class="specialist-missing-chart" role="img" aria-label="${esc(title)}: unavailable under current source coverage"><strong>${esc(title)}</strong><span>${esc(text)}</span><small>No sample chart is substituted.</small></div>`;}
function tabControls(ctx,items){const selected=items.some(([id])=>id===ctx.state.specialistView)?ctx.state.specialistView:items[0][0];return `<div class="specialist-chart-controls"><div class="segmented" aria-label="Chart view">${items.map(([id,label])=>`<button type="button" data-specialist-tab="${esc(id)}" aria-pressed="${id===selected}">${esc(label)}</button>`).join('')}</div><div class="segmented specialist-ranges" aria-label="History range">${['1M','1Y','3Y','5Y','MAX'].map(value=>`<button type="button" data-specialist-range="${value}" aria-pressed="${value===(ctx.state.specialistRange??'1Y')}">${value}</button>`).join('')}</div></div>`;}
function plot(ctx,views,{height=300,controls=true}={}){const selected=views.find(([id])=>id===ctx.state.specialistView)??views[0],ids=selected[2],rows=ids.flatMap(id=>ctx.get(id)?.observations??[]),end=rows.map(r=>r.date).sort().at(-1);let range={preset:({MAX:'all','3Y':'3y','5Y':'5y'})[ctx.state.specialistRange]??'1y'};if(ctx.state.specialistRange==='1M'&&end){const d=new Date(end+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);range={preset:'custom',startDate:d.toISOString().slice(0,10),endDate:end};}const body=rows.some(r=>finite(r.value))?chart(ids,{height,range,legend:true,endLabels:true}).replace('data-chart data-series','data-chart data-chart-catalog="specialist" data-series'):unavailableChart(selected[1],'The required official capture or measurement is unavailable.');return (controls?tabControls(ctx,views):'')+body+note(selected[3]??'Original source dates and missing values are retained.');}
function readings(ctx,rows){return `<dl class="specialist-reading-list">${rows.map(([label,id])=>{const s=ctx.get(id),r=last(s);return `<div data-specialist-input="${esc(id)}"><dt>${esc(label)}</dt><dd>${esc(deskValue(s,r))}</dd><small>${esc(r?.date??'Reference unavailable')} · ${esc(s?.unit??'Input unavailable')}</small></div>`;}).join('')}</dl>`;}
function rawTable(headers,rows,caption){return table(headers,rows.map(row=>'<tr>'+row.map((cell,i)=>i===0?`<th scope="row">${esc(cell??'—')}</th>`:`<td${typeof cell==='number'?' class="num"':''}>${esc(cell??'—')}</td>`).join('')+'</tr>').join(''),caption);}
function sourceDock(ctx){return `<section class="specialist-source-dock" id="specialist-lineage"><header><span class="eyebrow">Source access & local exports</span><h2>Programmatic research data & lineage</h2>${button('Download desk CSV','data-specialist-export')}</header><div class="specialist-source-grid"><div><p>Export retained observations, named tables, native units, calculation labels and actual source receipts for every source used by this desk.</p><pre><code>${esc('record_type,source_id,series_id,date,value,unit,observation_type,source_url,source_sha256,retrieved_at')}</code></pre><p>Observations, published projections, staff-model estimates and assumptions remain separate.</p></div><div>${ctx.contract.sources.map(id=>{const s=ctx.sources[id];return `<details><summary>${esc(id)} · ${s?.fetchedAt?(s.status==='ok'?'Captured':'Cached'):'Not loaded'}</summary><p>Last successful retrieval: ${esc(s?.fetchedAt??'Unavailable')}${s?.lastAttemptAt?` · Latest attempt ${esc(s.lastAttemptAt)}`:''}</p>${s?.error?`<p class="amber">${esc(s.error)}</p>`:''}<p>${esc(s?.coverageNote??'This required capture is not loaded. Coverage cannot be determined from an unloaded input.')}</p>${(s?.provenance??[]).map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a><small class="table-code">${esc(r.retrievedAt)} · SHA256 ${esc(r.sha256)}</small></p>`).join('')}${[...new Set(Object.values(s?.series??{}).map(v=>v.sourceNotice).filter(Boolean))].map(n=>`<p>${esc(n)}</p>`).join('')}</details>`;}).join('')}</div></div></section>`;}
function latestDates(ctx,ids,count=8){return [...new Set(ids.flatMap(id=>ctx.get(id)?.observations?.map(r=>r.date)??[]))].sort().slice(-count).reverse();}
const at=(ctx,id,date)=>ctx.get(id)?.observations.find(r=>r.date===date)?.value??null;
function weeklyPercentile(series){const latest=last(series);if(!finite(latest?.value))return missing;const dates=new Map((series.observations??[]).map(r=>[r.date,r.value])),values=Array.from({length:52},(_,i)=>dates.get(new Date(Date.parse(latest.date+'T00:00:00Z')-i*7*86400000).toISOString().slice(0,10)));return values.every(finite)?`${numeric(100*values.filter(v=>v<=latest.value).length/52,1,'%')} · n=52 exact weekly endpoints (≤ current)`:'52 exact weekly endpoints required';}
function repoOperationCells(ctx){const op=ctx.sources.repoOperations?.tables?.operations?.rows?.at(-1);if(!op)return null;const full=op.method==='Full Allotment',field=full?'offeringRate':'minimumBidRate',terms=(op.details??[]).map(r=>`${r.securityType}: ${numeric(r[field],2,'%')}`).join(' / ');return [`Fed regular repo · ${op.method} ${full?'offering rate':'minimum bid'}`,terms,...Array(5).fill('Not a transaction fixing'),numeric(finite(op.acceptedDollars)?op.acceptedDollars/1e9:null,3),'Treasury / agency / MBS','New York Fed',`${op.date} · ${op.operationId} · ${op.method}`];}
function parCompensationChange(ctx,tenor,months=0){const all=ctx.get('parInflationComp'+tenor)?.observations??[],current=all.at(-1);if(!finite(current?.value))return missing;const rows=all.filter(r=>r.date<current.date&&finite(r.value)),target=months?clampedMonthDate(current.date,months):null,prior=months?rows.find(r=>r.date===target):rows.at(-1);return prior?`${numeric(100*(current.value-prior.value),1,' bp')} · ${prior.date}`:`No exact ${target??'preceding matched observation'}`;}

