function sepDotPlot(source){const t=source?.tables?.dots,p=source?.tables?.projections;if(!t?.rows?.length)return unavailableChart('Anonymous SEP dot plot','The dated SEP capture is not loaded.');const rows=t.rows.filter(r=>r.count>0),hs=Object.keys(t.horizonCounts),levels=rows.map(r=>r.rate),low=Math.floor(Math.min(...levels)*2)/2-.25,high=Math.ceil(Math.max(...levels)*2)/2+.25,w=900,h=330,left=55,right=35,top=20,bottom=55,x=i=>left+(i+.5)*(w-left-right)/hs.length,y=rate=>top+(high-rate)/(high-low)*(h-top-bottom);let marks='';for(let r=Math.ceil(low*2)/2;r<=high;r+=.5)marks+=`<line x1="${left}" x2="${w-right}" y1="${y(r)}" y2="${y(r)}" class="specialist-svg-grid"/><text x="${left-8}" y="${y(r)+4}" text-anchor="end">${r.toFixed(1)}%</text>`;for(const r of rows){const i=hs.indexOf(r.horizon);for(let n=0;n<r.count;n++)marks+=`<circle class="sep-participant-dot" cx="${x(i)+(n-(r.count-1)/2)*9}" cy="${y(r.rate)}" r="3.4"><title>Anonymous participant · ${esc(r.horizon)} · ${r.rate}% · ${r.count} at this rate level</title></circle>`;}for(const[horizon,i]of hs.map((v,i)=>[v,i])){const median=p?.rows?.find(r=>r.variable==='federalFundsRate'&&r.horizon===horizon)?.median;if(finite(median))marks+=`<line class="sep-official-median" x1="${x(i)-45}" x2="${x(i)+45}" y1="${y(median)}" y2="${y(median)}"><title>Official rounded Table 1 median: ${median}%</title></line>`;marks+=`<text x="${x(i)}" y="${h-29}" text-anchor="middle">${esc(horizon)}</text><text x="${x(i)}" y="${h-11}" text-anchor="middle">n = ${t.horizonCounts[horizon]}</text>`;}return `<figure class="specialist-svg-figure"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Anonymous FOMC dot counts, ${esc(t.asOf)}"><title>SEP Figure 2 · anonymous participant counts by rate and horizon</title>${marks}</svg><figcaption>Anonymous dots: exact Figure 2 counts, nearest 1/8 percentage point. Dashed marks: separately published, rounded Table 1 median. Participants are never joined across years.</figcaption></figure>`;}
function fomcMeetings(ctx){const source=ctx.calendar?.sources?.fomc,reference=new Date(ctx.now),day=Number.isFinite(reference.getTime())?reference.toISOString().slice(0,10):null,events=day?(source?.events??[]).filter(e=>e.program==='fomc-decision'&&e.datePrecision==='day'&&e.date>=day).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,9):[];return events.length?events.map(e=>[e.date+(e.projectionsAssociated?' · SEP meeting':''),Math.round((Date.parse(e.date+'T00:00:00Z')-Date.parse(day+'T00:00:00Z'))/86400000),...Array(7).fill(missing),'Official scheduled date · Market probabilities unavailable']):[['FOMC schedule not loaded',...Array(8).fill(missing),'A retained official calendar is required.']];}
