 return kpis(ctx,[{label:'Current target range',value:`${deskValue(ctx.get('policyTargetLower'))} – ${deskValue(ctx.get('policyTargetUpper'))}`,basis:last(ctx.get('policyTargetUpper'))?.date??missing},{label:`${hs[0]??'Current year'} SEP median`,value:summary(get(hs[0])),basis:`${t?.projections?.asOf??missing} · official projection`},{label:`${hs[1]??'Next year'} SEP median`,value:summary(get(hs[1])),detail:'Official rounded Table 1 median',basis:t?.projections?.asOf??missing},{label:'Longer-run policy median',value:summary(get('Longer run')),detail:'Appropriate-policy projection',basis:t?.projections?.asOf??missing},{label:'Market minus Fed year-end wedge',value:missing,detail:'Matched futures/OIS unavailable'},{label:'Market-implied terminal rate',value:missing,detail:'Current futures strip not admitted'}])
